def f(xs):
    prune = lambda x: isinstance(x, int) and x % 2 == 0
    weave = lambda a, b: [aa for aa in a if aa] + [bb for bb in b if bb]
    curried_weave = lambda b: weave(xs, b)
    pruned_list = list(filter(prune, xs))
    return curried_weave(-1)(pruned_list)
